/*  This class pulls a color array from an image. The code is pulled from the following sources:
    https://thecodingtrain.com/challenges/186-wfc-overlapping-model
    https://editor.p5js.org/codingtrain/sketches/_7Pa8986g
		https://openprocessing.org/sketch/1607297

		Note that my I thought that it would be more efficient to add only unique colors to the color 
		array and then use replacemenet. I tried this and it was actually slower.  
*/

class ColorArray {
  constructor(res, img, TILE_W, TILE_H, debug = false, unique = false) {
    this.resolution = res;
    this.img = img;
    this.cols = this.img.width;
    this.rows = this.img.height;
    this.TILE_W = TILE_W;
    this.TILE_H = TILE_H;
    this.debug = debug;
    this.unique = unique;

    // Random tile position 
    this.i = floor(random(this.img.width - this.TILE_W));
    this.j = floor(random(this.img.height - this.TILE_H));
    if (this.debug) {
      console.log(`Tile starts at (${this.i}, ${this.j})`);
    }

    // Extract tile and generate color array
    this.tile = this.extractTile(this.i, this.j, this.img);
    this.colors = this.generateColorArray();
  }

  extractTile(i, j, img) {
    img.loadPixels();
    let tileImage = createImage(this.TILE_W, this.TILE_H);
    tileImage.loadPixels(); 
    this.copyTile(img, i, j, this.TILE_W, this.TILE_H, tileImage);
    tileImage.updatePixels();
    return tileImage;
  }

  copyTile(source, sx, sy, w, h, dest) {
    source.loadPixels();
    dest.loadPixels();
    for (let i = 0; i < w; i++) {
      for (let j = 0; j < h; j++) {
        let pixelI = (sx + i) % source.width;
        let pixelJ = (sy + j) % source.height;
        let srcIdx = (pixelI + pixelJ * source.width) * 4;
        let dstIdx = (i + j * dest.width) * 4;
        dest.pixels[dstIdx + 0] = source.pixels[srcIdx + 0]; // R
        dest.pixels[dstIdx + 1] = source.pixels[srcIdx + 1]; // G
        dest.pixels[dstIdx + 2] = source.pixels[srcIdx + 2]; // B
        dest.pixels[dstIdx + 3] = 255; // force alpha
      }
    }
  }

  generateColorArray() {
    let colors = [];
    this.tile.loadPixels();
    for (let i = 0; i < this.tile.width; i++) {
      for (let j = 0; j < this.tile.height; j++) {
        let index = (i + j * this.tile.width) * 4;
        let r = this.tile.pixels[index + 0];
        let g = this.tile.pixels[index + 1];
        let b = this.tile.pixels[index + 2];
        let a = this.tile.pixels[index + 3];
        let c = color(r, g, b, a);
        colors.push(this.p5ColorToUInt32(c));
      }
    }

    if (this.unique) {
      let uniqueColors = [...new Set(colors)];
      if (this.debug) console.log("Unique colors:", uniqueColors.length);
      return uniqueColors;
    }

    return colors;
  }

  p5ColorToHex(c, useHash) {
    let val = c.toString("#rrggbbaa");
    if (useHash) return val;

    return (
      "0x" +
      val.substring(7, 9) + // AA
      val.substring(5, 7) + // BB
      val.substring(3, 5) + // GG
      val.substring(1, 3) // RR
    );
  }

  p5ColorToUInt32(c) {
    return parseInt(this.p5ColorToHex(c, false));
  }

  drawTile(x, y) {
    image(this.tile, x, y);
  }
}


