const e = 2.71828;

class RainbowShape{
  constructor(
    bufferOffset,
    bufferSize,
    spacing,
    name = "Flower",
    angle = 0,
    scale = 0.5,
    numColors = 64,
    colors = null,
    xStart = 0.5,
    yStart = 0.5
  ) {
    this.bufferOffset = bufferOffset;
    this.bufferSize = bufferSize;
    this.spacing = spacing;
    this.rows = floor(this.bufferSize.y / spacing);
    this.cols = floor(this.bufferSize.x / spacing);
    this.name = name;
    this.angle = angle;
    this.scale = scale;
    this.done = false;
    this.colors = colors;
    this.xStart = xStart;
    this.yStart = yStart;
    //console.log(this.colors)

    this.grid = Array(this.rows)
      .fill()
      .map(() => Array(this.cols).fill(null));
    this.pg = createGraphics(
      this.bufferSize.x,
      this.bufferSize.y
    );
    this.pg.noStroke();
    this.uintPallete = null;
    this.numColors = numColors;
    if (this.colors) {
      this.uintPalette = this.colors;
    } else {
      this.uintPalette = this.generateUintPalette();
    }
    //console.log(this.uintPalette)
    shuffle(this.uintPalette, true);
    this.available = new Set();

    let center = createVector(
      this.pg.width / 2 + this.bufferOffset.x,
      this.pg.height / 2 + this.bufferOffset.y
    );

    this.shapePoints = this.generateShape(
      center,
      this.scale * min(this.pg.width, this.pg.height)
    );

    this.sx = floor(this.cols * this.xStart);
    this.sy = floor(this.rows * this.yStart);

    this.setColor(this.sx, this.sy, this.uintPalette.shift());
    this.addNeighbors(this.sx, this.sy);
  }

  generateUintPalette() {
    let list = [];
    for (let r = 0; r < this.numColors; r++) {
      for (let g = 0; g < this.numColors; g++) {
        for (let b = 0; b < this.numColors; b++) {
          const R = floor((r * 255) / (this.numColors - 1));
          const G = floor((g * 255) / (this.numColors - 1));
          const B = floor((b * 255) / (this.numColors - 1));
          const A = 255;
          const uint = (A << 24) | (B << 16) | (G << 8) | R;
          list.push(uint >>> 0); // Ensure unsigned
        }
      }
    }
    return list;
  }

  generateShape(center, r) {
    switch (this.name) {
      case "Astroid":
        return this.astroid(center, r);
      case "Bicorn":
        return this.bicorn(center, r);
      case "Craniod":
        return this.craniod(center, r);
      case "Clover":
        return this.clover(center, r);
      case "Fish":
        return this.fish(center, r);
      case "Flower":
        return this.flower(center, r);
      case "Gear":
        return this.gear(center, r);
      case "Heart":
        return this.heart(center, r);
      case "Kiss":
        return this.kiss(center, r);
      case "Polygon":
        return this.polygon(center, r);
      case "Superellipse":
        return this.superellipse(center, r);
      case "Supershape":
        return this.supershape(center, r);
      case "Tear":
        return this.tear(center, r);
      default:
        return [];
    }
  }

  rotateShapePoints(center, angle) {
    for (let p of this.shapePoints) {
      let v = p.copy().sub(center);
      v.rotate(angle);
      p.set(v.add(center));
    }
  }

  astroid(center, sc, a = 1, b = 1.3) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.05) {
      let x = center.x + sc * a * pow(cos(theta), 3);
      let y = center.y + sc * b * pow(sin(theta), 3);
      points.push(createVector(x, y));
    }
    return points;
  }

  // This one isn't working yet.  I think the seed point has to be somewhere in shape
  bicorn(center, sc) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.05) {
      let x = center.x + sc * sin(theta);
      let y = center.y + (sc * pow(cos(theta), 2)) / (2 + cos(theta));
      points.push(createVector(x, y));
    }
    return points;
  }

  clover(center, sc, m = 4) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.05) {
      let r = 1 + cos(m * theta) + pow(sin(m * theta), 2);
      let x = center.x + sc * r * cos(theta);
      let y = center.y + sc * r * sin(theta);
      points.push(createVector(x, y));
    }
    return points;
  }

  // https://mathworld.wolfram.com/Cranioid.html
  craniod(center, sc, a = 1, b = 3, m = 0, p = 0.75, q = 0.75) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.05) {
      let r =
        a * sin(theta) +
        b * sqrt(1 - p * pow(cos(theta), 2)) +
        m * sqrt(1 - q * pow(cos(theta), 2));
      let x = center.x + sc * r * cos(theta);
      let y = center.y + sc * r * sin(theta);
      points.push(createVector(x, y));
    }
    return points;
  }

  fish(center, sc) {
    let points = [];
    for (let theta = -TWO_PI; theta < TWO_PI; theta += 0.05) {
      let x = center.x + sc * 0.75 * (cos(theta) + 2 * 2 * cos(theta / 2));
      let y = center.y + sc * 1.0 * sin(theta);
      points.push(createVector(x, y));
    }
    return points;
  }

  flower(center, sc, a = 1.25, m = 8) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.01) {
      let r = a + cos(m * theta);
      let x = center.x + sc * r * cos(theta);
      let y = center.y + sc * r * sin(theta);
      points.push(createVector(x, y));
    }
    return points;
  }

  // https://mathworld.wolfram.com/GearCurve.html
  // https://help.tc2000.com/m/69445/l/755460-hyperbolic-functions-table
  hyperbolicTan(theta) {
    let l = pow(e, 2 * theta);
    return (l - 1) / (l + 1);
  }

  gear(center, sc, a = 1, b = 4, m = 8) {
    let points = [];
    for (let theta = 0; theta < 2 * PI; theta += 0.025) {
      let r = a + (1 / b) * this.hyperbolicTan(b * sin(m * theta));
      let x = center.x + sc * r * sin(theta);
      let y = center.y + sc * r * cos(theta);
      points.push(createVector(x, y));
    }
    return points;
  }

  // heart curve equation from https://mathworld.wolfram.com/HeartCurve.html
  // https://thecodingtrain.com/challenges/134-heart-curve
  heart(center, r) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.1) {
      const x = center.x + 0.1 * r * 16 * pow(sin(theta), 3);
      const y =
        center.y +
        0.1 *
          -r *
          (13 * cos(theta) -
            5 * cos(2 * theta) -
            2 * cos(3 * theta) -
            cos(4 * theta));
      points.push(createVector(x, y));
    }
    return points;
  }

  kiss(center, r, a = 2.1, b = 1.1) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.05) {
      let v0 = center.x + a * r * cos(theta);
      let v1 = center.y + b * r * pow(sin(theta), 3);
      points.push(createVector(v0, v1));
    }
    return points;
  }

  polygon(center, sc, m = 4) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += (Math.max(0.001, Math.abs(TWO_PI / m)) || 1)) {
      let x = center.x + sc * cos(theta);
      let y = center.y + sc * sin(theta);
      points.push(createVector(x, y));
    }
    return points;
  }

  // https://thecodingtrain.com/challenges/19-superellipse
  sgn(val) {
    if (val == 0) {
      return 0;
    }
    return val / abs(val);
  }

  superellipse(center, sc, a = 1, b = 2, m = 6) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.05) {
      let na = 2 / m;
      let x =
        center.x + sc * pow(abs(cos(theta)), na) * a * this.sgn(cos(theta));
      let y =
        center.y + sc * pow(abs(sin(theta)), na) * b * this.sgn(sin(theta));
      points.push(createVector(x, y));
    }
    return points;
  }

  // https://thecodingtrain.com/challenges/23-2d-supershapes
  superformula(theta, a = 1, b = 1, m = 8, n1 = 1, n2 = 1, n3 = 1) {
    let part1 = abs((1 / a) * cos((theta * m) / 4));
    part1 = pow(part1, n2);
    let part2 = abs((1 / b) * sin((theta * m) / 4));
    part2 = pow(part2, n3);
    let part3 = pow(part1 + part2, 1 / n1);
    return part3 === 0 ? 0 : 1 / part3;
  }

  supershape(center, sc) {
    let points = [];
    for (let theta = 0; theta <= TWO_PI; theta += 0.01) {
      let r = this.superformula(theta);
      let x = center.x + sc * r * cos(theta);
      let y = center.y + sc * r * sin(theta);
      points.push(createVector(x, y));
    }
    return points;
  }

  // https://mathcurve.com/courbes2d.gb/larme/larme.shtml
  tear(center, sc, n = 4) {
    let points = [];
    for (let theta = 0; theta < TWO_PI; theta += 0.1) {
      let x = center.x + sc * cos(theta);
      let y = center.y + sc * sin(theta) * pow(sin(theta / 2), n);
      points.push(createVector(x, y));
    }
    return points;
  }

  // rotateShapePoints(center, angle) {
  //   for (let p of this.shapePoints) {
  //     let v = p.copy().sub(center);
  //     v.rotate(angle);
  //     p.set(v.add(center));
  //   }
  // }

	// Utility function from chatGPT
  isInsideShape(px, py) {
    let points = this.shapePoints;
    let count = 0;
    for (let i = 0; i < points.length; i++) {
      let a = points[i];
      let b = points[(i + 1) % points.length];
      if (a.y > py !== b.y > py) {
        let t = (py - a.y) / (b.y - a.y);
        let x = a.x + t * (b.x - a.x);
        if (x > px) count++;
      }
    }
    return count % 2 === 1;
  }

  setColor(x, y, c) {
    let px = x * this.spacing + this.bufferOffset.x;
    let py = y * this.spacing + this.bufferOffset.y;
    if (!this.isInsideShape(px, py)) return;

    this.grid[y][x] = c;

    // Unpack UInt32 -> R,G,B
    let r = c & 0xff;
    let g = (c >> 8) & 0xff;
    let b = (c >> 16) & 0xff;
    this.pg.fill(r, g, b);

    this.pg.rect(
      x * this.spacing,
      y * this.spacing,
      this.spacing,
      this.spacing
    );
  }

  getColor(x, y) {
    return this.grid[y][x];
  }

  addNeighbors(x, y) {
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        let nx = x + dx;
        let ny = y + dy;
        let px = nx * this.spacing + this.bufferOffset.x;
        let py = ny * this.spacing + this.bufferOffset.y;
        if (
          nx >= 0 &&
          nx < this.cols &&
          ny >= 0 &&
          ny < this.rows &&
          this.grid[ny][nx] === null &&
          this.isInsideShape(px, py)
        ) {
          this.available.add(`${nx},${ny}`);
        }
      }
    }
  }

  calcDiff(x, y, c) {
    let diffs = [];
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        let nx = x + dx;
        let ny = y + dy;
        if (nx >= 0 && nx < this.cols && ny >= 0 && ny < this.rows) {
          let nc = this.grid[ny][nx];
          if (nc !== null) diffs.push(this.colorDiffUint(nc, c));
        }
      }
    }
    return diffs.length ? min(diffs) : Infinity;
  }

  colorDiffUint(c1, c2) {
    const r1 = c1 & 0xff;
    const g1 = (c1 >> 8) & 0xff;
    const b1 = (c1 >> 16) & 0xff;

    const r2 = c2 & 0xff;
    const g2 = (c2 >> 8) & 0xff;
    const b2 = (c2 >> 16) & 0xff;

    const dr = r1 - r2;
    const dg = g1 - g2;
    const db = b1 - b2;
    return dr * dr + dg * dg + db * db;
  }

  step() {
    if (this.uintPalette.length === 0 || this.available.size === 0) {
      this.done = true;
      return;
    }
    let bestXY = null;
    let bestDiff = Infinity;
    let c = this.uintPalette[0];

    for (let key of this.available) {
      let [x, y] = key.split(",").map(Number);
      let diff = this.calcDiff(x, y, c);
      if (diff < bestDiff) {
        bestDiff = diff;
        bestXY = [x, y];
      }
    }

    if (bestXY) {
      let [x, y] = bestXY;
      this.setColor(x, y, c);
      this.uintPalette.shift();
      this.available.delete(`${x},${y}`);
      this.addNeighbors(x, y);
    }
  }

	 dispose() {
    if (this.pg && this.pg.remove) {
      this.pg.remove();
      this.pg = null; // Optional: prevent accidental future use
    }
  }

  showShape() {
    this.pg.push();
    this.pg.stroke(59);
    this.pg.noFill();
    this.pg.beginShape();
    for (let p of this.shapePoints) {
      this.pg.vertex(p.x - this.bufferOffset.x, p.y - this.bufferOffset.y);
    }
    this.pg.endShape(CLOSE);
    this.pg.pop();
  }

	findSeedPoint() {
    push()
    fill(0, 0, 255);
    noStroke();
    circle(this.sx, this.sy, 10);
    pop()
  }

	/* Optional: Draw circle at seed point and red rectangle around buffer for debugging 
	*/
  sanityCheck() {
    stroke(255, 0, 0);
    noFill();
    push();
    translate(this.bufferOffset.x + this.pg.width / 2, this.bufferOffset.y + this.pg.height / 2);
    rotate(this.angle);
    this.findSeedPoint()
    rectMode(CENTER);
    rect(0, 0, this.pg.width, this.pg.height);
    pop();
  }

  show() {
    push();
    translate(
      this.bufferOffset.x + this.pg.width / 2,
      this.bufferOffset.y + this.pg.height / 2
    );
    rotate(this.angle);
    imageMode(CENTER);
    image(this.pg, 0, 0);
    pop();
  }
}


