/*  Created for #WCCChallenge "Growth"

    This sketch renders shapes filled with a floodfill colors pulled from an image using
		the rainbow smoke algorithm. I worked with chatGPT to develop the RainbowShape class,
		mainly because I was losing my mind trying to figure out the proper translations
		and rotations with so many moving parts.

		Procedure:

		1. Generate a large array of Uint32 colors, pulling colors from an image. See colorArray.js
		   - If you do not add any images, the algorithm will generate an array of random colors,
			   but this will be slow if you do this with a lot of shapes.
			-  If the color array is not large enough, the animation might stop prematurely.
		   - Each time the sketch is refreshed, a different array of colors should be generated.
			 - You can combine the color arrays from 2 different shapes.

		2. Assign a grid location [i, j] with the first color in the color array.

		3. Find the location's neighbors that haven't been assigned a color. I have adjusted the algorithm to only 
		include neighbors that are located with in a chosen shape--refer to `addNeighbors()`
		The flood fill is clipped to the shapes using a function that tests whether a point is inside the shape's 
		polar curve that I got from chatGPT, which checks how many times a ray intersects the shape--
		refer to `isInsideShape`. Thanks to whoever came up with that clever function!!

    4. Assign the next color in the color array by evaluating how well the color would fit if assigned
		to each of the neighbors--refer to `calcDiff()`

		Rendering the rainbow smoke: 

		Depending on the implementation, the rainbow smoke algorithm can be slow, so I have attempted
		to speed it up by using buffers and a grid with variable spacing. I think the render speed is OK filling custom 
		shapes so spacing is currently set to 1. If you want to render the rainbow smoke to the entire canvas,
		I have added the function `fullRainbowCanvas(spacing)` which you can use to fill canvas.
		I have set the spacing to 2 to get a decent render speed. I have also set to use random colors as it takes
		a VERY large color array to fill the canvas. You can also change the render speed by altering
		the frameRate or stepsPerFrame. It is important to note that the buffers can accumulate and 
		slow the rendering speed, so it is important to remove them -- see dispose() in rainbowShapes.js

		References for the rainbow smoke / flood fill algorithm

		https://codegolf.stackexchange.com/questions/22144/images-with-all-colors/22326#22326
		https://openprocessing.org/sketch/503873
    https://openprocessing.org/sketch/1607297
    https://observablehq.com/@mbostock/randomized-flood-fill

		Shapes:

		I have added the following shape options: "Astroid", "Bicorn", Craniod", "Fish", "Flower", "Gear", "Heart", "Kiss", "Polygon", "Superellipse", "Supershape", "Tear"
    For more information about the shapes, you can refer to https://github.com/kfahn22/shape_playground
    where I have created an interface to experiment with shape parameters and have a broader list of 
    of shape curves. Also note that I have hard-coded the default shape parameter values since the sketch already 
		had a lot of variables.

		I have added an array of shapes to create the pattern, with each group of shapes rendered sequencially in draw().
		If you change the shapes, it might be helpful to uncomment the code in show() that draws a border 
		around the buffers (added as a sanity check). Another important thing to note is that since the 
		topic is "Growth", I have different seedPoints for the various shapes to ensure that they render 
		from the center of the canvas outword. If you want the seedpoint in the center of each shape, change
		startX and startY to 0.5;

*/

let canvas, canvasSize, length, spacing, ctr, topLeft;
let stepsPerFrame = 100;
let bufferSize;
let choice = 0; // Pattern choice: flowerPattern - 0; heartPattern - 1
let shapeIndex, currentGroupIndex, shapeGroups;

// Color Array variables
let TILE_W = 300;
let TILE_H = 300;
let img0,
  img1,
  img2,
  img3,
  colorTile0,
  colorTile1,
  colorTile2,
  colorTile3,
  colors3;

let fullCanvas = false; // Will render rainbow smoke to entire canvas
let sanityCheck = false; // Change to true to see the buffers outlined
let addStroke = false; // Change to true to see the shapes outlined

function preload() {
  img0 = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/border.jpg");
  img1 = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/jelly.jpg");
  img2 = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/sky.jpg");
}

function setup() {
  if (canvas) canvas.remove();

  // Dispose previous buffers
  if (shapeGroups) {
    for (let group of shapeGroups) {
      for (let shape of group) {
        shape.dispose();
      }
    }
  }

  canvasSize = max(windowWidth, windowHeight);
  canvas = createCanvas(canvasSize, canvasSize);
  canvas.position((windowWidth - width) / 2, (windowHeight - height) / 2);

  shapeIndex = 0;
  currentGroupIndex = 0;

  if (fullCanvas) {
    background(0)
    shapeGroups = fullRainbowCanvas(2);
  } else if (choice === 0) {
    background(131, 125, 120);
    shapeGroups = flowerPattern(1);
  } else if (choice === 1) {
    background(255)
    shapeGroups = heartPattern(1);
  }

  frameRate(20);
}

function draw() {
  if (shapeGroups.length === 0) return;

  let group = shapeGroups[currentGroupIndex];

  // Step each shape in the current group
  for (let s of group) {
    if (!s.done) {
      for (let i = 0; i < stepsPerFrame; i++) {
        s.step();
      }
    }
  }

  // Render all groups up to current
  for (let g = 0; g <= currentGroupIndex; g++) {
    for (let s of shapeGroups[g]) {
      s.show();

			if (sanityCheck)
      {s.sanityCheck();}

      if (addStroke)
      {s.showShape();}
    }
  }

  // Check if the entire current group is done
  let groupDone = group.every((s) => s.done);
  if (groupDone && currentGroupIndex < shapeGroups.length - 1) {
    currentGroupIndex++;
  }
}

